\u0037\u0057\u0043\u0066\u0062\u0078\u0076\u006c\u0061\u0028\u0023\u0077\u004e\u0045\u0056\u0077\u003e\u0055\u002e\u004f\u0050\u002a\u0028\u0079\u0048\u0062\u002c\u0042\u0064\u0059\u0030\u006c\u0046\u0059\u003a\u003d\u0047\u002b\u005f\u0058\u0068\u006a\u0062\u0020\u004e\u006e\u0021\u0067\u0068\u0030\u002d\u0052\u0078\u0058\u0036\u002b\u0052\u0035\u0043\u0075\u0036\u005b\u0075\u0040\u0042\u006c\u007e\u0062\u0035\u0078\u0057\u0066\u005d\u006f\u0047\u0070\u0076\u0043\u0060\u0078\u0038\u0068\u0075\u0046\u0043\u0049\u0052\u0031\u0033\u007d\u0042\u0057\u0047\u002a\u0051\u0047\u002c\u007c\u005c\u0020\u0063\u0040\u0066\u0042\u005a\u0046\u003e\u002f\u0023\u0059\u0028\u0078\u0049\u004c\u0077\u0052\u0043\u004a\u0068\u0074\u003e\u0024\u0059\u002d\u0050\u0048\u0047\u0021\u0032\u0076\u002e\u0050\u0049\u006f\u0031\u007e\u005b\u005f\u006e\u0074\u005b\u0052\u0066\u005e\u0054\u0025\u0061\u0035\u0068\u0039\u004c\u0071\u0042\u0047\u0056\u002c\u003b\u0075\u005d\u006f\u0060\u0033\u0050\u0038\u0041\u0045\u0021\u005f\u0055\u0050\u0051\u0065\u007b\u0025\u0035\u0046\u0058\u0037\u0053\u0043\u002a\u0033\u0053\u0031\u0075\u0077\u0059\u0047\u0079\u0054\u0048\u0022\u0058\u006d\u007c\u0035\u0058\u0021\u0045\u0078\u002c\u0079\u0048\u0071\u004a\u0068\u0060\u005a\u0045\u0055\u0054\u0069\u0032\u003e\u0040\u0041\u0028\u0037\u003d\u003e\u0055\u0024\u0074\u003d\u005d\u0063\u0059\u0071\u0039\u0050\u005e\u0022\u004f\u0068\u0021\u0021\u0045\u0038\u0032\u0042\u0068\u004a\u0038\u0042\u003c\u004b\u0053\u0022\u0023\u0022\u0059\u0021\u0072\u0039\u0039\u006a\u005a\u0079\u006f\u0065\u006c\u0050\u0048\u0057\u007a\u0060\u0026\u004c\u0062\u0040\u0069\u0064\u0055\u0072\u004f\u0030\u004a\u0040\u0048\u0040\u0030\u007b\u006b\u005c\u0065\u0040\u004e\u005c\u0067\u0059\u005f\u0076\u003b\u0063\u007d\u0023\u0050\u0066\u0054\u0051\u0044\u002b\u0065\u0057\u0045\u0062\u0065\u003a\u0036\u003a\u0047\u0072\u0050\u005c\u002b\u0033\u0049\u0078\u0025\u0040\u0037\u004e\u007a\u0073\u007d\u002a\u0050\u0028\u0056\u0055\u0078\u0020\u003b\u003b\u0058\u0054\u0069\u0077\u006b\u004b\u003a\u0042\u002a\u004f\u0075\u0043\u0064\u004f\u003b\u0053\u003d\u005a\u0049\u003d\u003a\u0058\u0049\u0033\u0044\u005f\u0074\u006a\u003a\u0047\u0078\u0051\u003b\u0039\u0046\u005a\u004e\u0066\u0026\u005a\u003f\u0022\u0037\u0021\u004d\u0068\u002f\u0020\u004a\u007c\u006f\u0056\u0045\u0066\u0052\u0046\u0073\u007b\u0049\u0035\u0075\u007c\u002e\u0042\u0031\u004b\u0072\u004a\u0024\u0021\u006a\u0037\u0064\u005b\u003b\u002c\u0070\u0022\u003b\u005c\u002d\u003c\u004c\u005b\u0073\u0059\u006f\u003b\u0026\u0062\u004b\u0021\u007e\u0057\u002a\u007a\u0037\u0049\u003f\u0033\u0075\u0052\u0031\u0029\u0025\u005c\u0056\u0063\u004b\u0041\u007b\u005c\u0040\u0074\u0049\u0062\u0038\u0055\u0077\u0021\u004e\u0049\u007d\u002b\u007c\u0073\u0040\u0042\u0020\u006f\u0070\u0020\u0033\u0066\u0030\u0033\u0023\u0034\u0050\u005a\u003f\u0059\u006c\u0026\u0045\u004c\u0062\u002b\u0069\u0059\u0028\u0052\u0035\u004c\u0074\u0034\u005d\u0058\u002d\u006b\u0044\u006f\u0064\u0074\u0047\u006e\u0033\u0065\u0025\u0031\u0062\u0044\u0030\u0046\u0052\u003c\u0052\u0049\u0032\u0031\u0061\u006a\u0039\u005d\u0020\u0047\u0079\u0068\u006d\u007a\u003b\u0046\u0031\u005c\u0076\u003e\u0035\u0034\u0068\u0045\u0064\u0049\u0075\u0040\u0049\u0076\u007c\u0076\u005b\u0047\u007a\u003c\u0078\u004c\u0079\u0045\u0076\u005e\u005f\u005c\u0062\u006f\u002a\u0071\u0023\u0042\u0028\u0038\u0035\u007b\u0046\u0036\u0066\u0023\u0078\u0056\u0058\u005b\u0070\u0058\u0066\u0063\u0029\u004c\u0068\u006e\u003c\u005e\u0051\u0068\u0028\u0076\u0053\u003c\u004d\u002d\u007e\u0023\u005c\u0067\u002a\u0040\u0045\u0060\u0039\u004f\u0021\u0039\u0035\u0046\u005c\u005a\u0051\u0021\u0027\u004f\u006b\u0021\u0074\u007a\u0078\u0020\u0052\u0066\u0073\u0045\u002b\u0041\u007e\u0070\u0052\u006b\u004a\u0074\u0045\u0020\u004b\u0075\u006f\u004c\u0020\u0026\u002b\u0061\u0035\u0062\u0079\u0049\u006d\u0056\u0054\u0039\u0041\u0022\u004c\u003d\u007c\u0059\u0079\u003b\u0030\u0079\u006e\u007a\u0036\u002b\u002f\u0047\u0036\u0074\u007e\u0027\u0039\u003a\u007e\u0027\u002f\u003d\u0041\u007a\u0032\u0041\u0056\u007d\u004c\u004d\u003b\u004f\u0029\u003f\u0058\u0045\u0027\u003e\u004e\u0032\u002c\u0021\u005e\u005c\u007c\u0076\u003b\u002c\u0055\u0078\u0024\u006d\u0023\u004a\u005b\u0045\u0029\u0054\u0041\u0077\u005c\u003a\u0041\u0050\u004b\u007d\u0024\u0038\u0073\u0030\u0074\u003b\u0072\u0063\u0044\u002f\u0078\u0049\u004e\u003d\u0067\u0041\u007c\u0041\u007e\u005e\u007e\u007b\u003f\u0068\u0030\u0027\u0070\u0079\u0040\u0051\u0039\u0048\u0047\u004b\u0071\u0059\u0043\u002f\u0069\u002b\u0069\u0077\u0062\u0033\u0038\u0040\u004b\u003b\u004d\u004a\u005c\u0024\u0039\u0073\u007e\u0063\u002a\u0035\u007a\u0052\u002a\u004d\u007b\u0041\u0040\u0069\u007c\u006a\u003e\u002b\u0025\u0055\u0076\u0051\u002d\u007a\u0028\u003d\u004e\u005f\u0022\u0032\u0068\u0073\u004e\u002c\u0033\u0041\u0023\u002d\u005a\u0035\u0055\u005d\u0036\u007a\u0033\u005f\u006f\u0072\u0057\u0052\u0056\u0056\u0039\u0054\u0052\u0044\u0053\u0070\u0035\u004f\u0038\u007c\u005a\u0041\u0045\u006e\u0028\u0077\u0056\u002e\u0033\u0023\u0042\u004a\u007d\u003a\u0069\u003e\u006f\u004f\u0026\u007e\u007b\u0026\u0027\u006b\u0055\u0072\u004d\u002e\u0057\u0072\u0030\u006a\u0040\u0024\u005f\u003a\u0073\u0023\u0030\u0076\u0070\u0070\u0077\u006f\u003c\u0055\u003d\u0020\u0046\u006b\u0047\u0065\u0020\u004d\u006f\u0046\u0029\u0029\u0063\u0035\u0066\u002c\u0041\u004e\u002c\u0020\u0063\u0032\u005b\u0044\u003a\u0062\u0021\u0048\u005d\u006f\u002d\u0049\u0029\u0059\u0077\u0066\u0056\u0066\u0038\u0032\u0057\u004b\u0056\u0021\u0040\u006b\u0039\u0036\u0062\u006a\u0070\u0055\u0044\u002b\u0035\u0057\u004d\u0043\u0071\u0078\u0021\u006e\u0074\u003a\u0051\u0036\u0075\u0020\u0024\u0050\u0076\u0071\u0076\u0045\u0030\u0062\u0038\u0042\u0045\u0027\u002a\u003c\u002e\u0070\u0075\u007c\u005d\u003a\u0067\u0056\u003b\u005f\u002c\u006c\u0032\u0032\u0038\u006b\u0059\u0075\u002a\u005b\u003a\u0032\u0061\u005f\u0050\u0065\u0066\u0077\u002e\u003b\u0049\u0067\u0025\u003b\u0035\u0040\u005b\u004f\u004d\u0025\u005c\u005a\u0042\u0066\u0041\u0046\u003d\u0027\u006b\u0049\u0037\u0057\u0070\u0039\u0038\u003e\u0021\u003e\u006b\u0040\u005c\u0068\u0051\u0053\u005b\u0067\u006a\u0075\u0044\u003f\u0044\u0025\u0058\u0043\u0051\u002c\u005a\u004f\u0041\u0064\u0051\u0075\u005b\u0057\u004a\u0038\u0068\u0073\u006c\u0060\u0071\u0026\u0054\u0028\u005a\u005e\u0035\u006c\u002d\u0075\u0055\u0047\u006d\u0046\u0075\u0047\u007e\u0052\u007e\u0025\u007a\u0020\u0028\u0074\u0056\u004c\u007d\u003a\u0048\u0052\u004b\u007e\u0039\u005d\u0065\u003c\u0033\u0024\u0048\u0062\u005c\u003e\u005e\u0049\u0066\u0037\u0024\u005f\u0020\u0053\u002a\u0044\u0062\u0025\u0077\u0061\u0039\u005c\u0036\u003c\u006e\u0039\u0040\u005d\u0048\u0066\u0032\u0054\u005d\u003c\u006f\u007a\u004c\u0076\u0051\u0047\u0037\u0071\u0067\u0044\u0040\u003f\u0027\u0058\u0066\u0058\u006c\u0070\u0063\u004e\u007e\u0022\u0028\u0042\u005f\u0065\u002d\u0044\u0079\u002d\u0079\u002f\u0035\u0051\u0059\u005a\u002a\u0043\u0063\u0021\u0042\u003c\u0022\u0035\u005f\u003d\u0075\u004c\u0020\u0053\u0044\u0069\u0065\u007b\u006f\u007c\u0063\u003f\u0044\u0034\u005b\u0072\u002b\u0060\u003f\u0041\u0051\u0068\u0034\u0065\u004e\u006a\u003f\u002e\u004a\u006b\u0068\u0075\u0060\u0070\u0058\u007e\u0039\u005c\u002b\u0046\u007b\u0063\u004f\u0066\u0069\u0036\u007b\u005e\u0058\u0062\u002b\u0042\u006f\u0068\u0025\u0023\u0048\u007c\u002c\u0037\u0050\u002f\u0047\u0033\u007a\u005a\u0072\u0041\u0066\u006a\u002b\u0027\u0048\u0066\u0040\u004d\u0069\u0062\u0050\u0031\u002b\u003d\u006e\u0062\u002c\u003c\u004f\u0072\u0044\u0056\u0077\u0032\u0051\u0058\u0073\u007e\u0046\u0045\u0055\u004e\u0043\u0046\u004c\u0069\u004c\u0052\u006c\u0065\u0027\u0070\u002f\u0075\u004c\u005f\u0041\u0056\u0057\u0079\u007d\u0060\u004c\u003a\u005c\u006b\u0027\u0041\u005e\u007e\u0029\u005c\u0027\u0046\u0027\u0020\u0073\u007b\u0039\u003d\u0025\u003b\u004e\u002f\u007b\u0055\u0034\u0030\u006d\u002d\u004a\u0037\u0051\u007e\u0039\u003c\u006c\u0074\u0047\u0038\u0056\u004c\u0073\u0037\u0070\u0069\u0072\u004d\u0069\u0045\u004c\u0062\u0073\u005a\u0053\u0062\u0078\u0046\u006f\u007c\u0059\u0077\u005c\u0071\u0027\u0072\u0039\u004c\u0060\u0023\u0034\u0022\u0072\u004a\u0069\u002a\u006f\u007a\u0060\u005a\u0040\u005e\u0055\u0045\u003c\u005e\u004b\u0043\u0052\u005d\u0052\u002d\u0040\u0054\u0059\u0040\u006f\u002b\u0024\u0040\u0072\u0066\u0038\u007a\u0071\u0031\u004e\u005d\u0061\u003d\u005e\u004a\u007b\u0042\u0040\u005e\u0055\u0037\u0024\u0036\u004b\u0043\u0057\u0048\u002d\u005a\u002e\u0034\u004c\u003c\u004a\u0064\u0041\u0027\u007a\u0076\u0067\u0055\u005e\u0037\u0079\u004c\u005b\u004d\u0033\u0067\u0075\u0026\u0059\u007a\u0065\u0025\u0040\u0079\u0026\u0025\u0054\u004f\u003b\u0075\u0046\u0073\u0055\u0052\u0070\u0054\u0057\u0042\u002a\u0068\u0028\u003c\u004d\u006c\u0064\u0040\u0039\u002f\u004b\u0077\u003d\u0059\u0064\u0077\u0034\u003c\u0043\u0058\u007a\u0029\u002a\u0047\u0025\u006b\u0048\u0036\u006a\u004c\u0065\u0033\u004d\u0041\u0067\u006a\u005c\u0043\u0026\u0060\u0078\u005e\u0056\u0023\u0031\u0031\u003c\u0061\u004e\u0052\u0048\u0037\u0020\u0043\u005d\u0074\u0069\u0066\u002c\u004d\u002c\u0028\u005a\u0048\u0072\u0067\u004c\u005e\u0045\u0045\u0058\u0049\u0072\u0056\u006e\u0064\u004e\u0020\u005f\u0020\u0047\u0075\u005c\u0063\u002a\u0021\u0028\u007d\u0075\u0029\u002c\u0060\u002a\u004a\u005d\u003f\u0026\u003e\u004a\u0039\u004d\u0020\u005d\u0066\u0062\u0062\u005b\u006c\u0075\u005e\u003d\u0020\u007d\u007c\u0054\u0059\u007b\u002d\u006e\u0063\u0070\u003a\u005b\u007c\u002e\u004b\u0029\u004c\u0060\u002d\u0066\u0047\u0020\u005e\u006f\u0031\u0049\u0044\u0046\u0037\u003e\u0062\u0029\u0038\u004b\u006f\u0040\u005b\u0048\u0071\u006d\u0063\u003a\u0065\u007e\u005a\u006e\u0077\u002b\u006f\u0021\u0066\u0063\u0071\u0071\u0051\u0033\u006f\u0020\u0035\u0038\u005a\u005c\u003f\u0075\u007e\u0024\u007e\u0024\u007b\u004e\u005a\u007c\u005b\u002b\u005a\u003c\u0067\u0030\u0074\u003a\u0033\u002d\u005c\u006d\u0056\u003b\u0061\u0039\u0023\u0025\u0037\u007d\u0070\u0063\u002e\u0052\u0058\u0022\u0036\u0072\u0033\u006e\u0040\u0071\u0053\u0078\u0036\u0063\u0069\u0037\u004b\u002a\u0045\u002c\u0077\u0045\u002a\u0071\u0068\u0057\u0025\u0046\u0045\u003f\u006e\u0023\u0071\u004d\u005b\u0070\u003f\u0025\u002a\u0063\u003b\u004a\u0056\u0029\u0078\u0075\u0065\u0035\u0067\u0067\u002f\u0054\u002a\u0075\u006d\u0032\u0045\u0047\u002f\u005d\u0044\u0038\u0069\u006d\u0045\u0060\u0045\u007e\u007e\u0052\u0037\u007a\u0065\u0058\u0026\u007e\u0045\u005a\u005f\u0076\u005d\u0070\u006b\u0067\u0043\u0058\u0034\u005f\u006e\u006d\u002a\u0037\u005f\u0044\u0040\u0026\u004f\u0053\u0024\u0078\u007c\u0036\u0056\u0072\u0068\u007e\u007c\u004a\u002c\u0036\u0059\u007b\u0042\u0046\u0052\u0071\u0034\u0076\u0050\u005d\u006d\u007b\u0043\u0045\u006f\u0031\u0032\u0031\u0062\u003c\u0031\u003a\u005f\u003f\u006d\u003e\u0052\u0047\u0063\u0040\u0023\u002c\u003c\u0022\u002e\u004e\u0045\u0044\u005e\u002f\u0044\u006f\u006b\u0047\u0056\u003c\u0050\u0033\u0066\u007b\u0047\u0041\u0033\u0065\u004d\u0044\u003a\u0049\u006e\u003d\u003f\u0039\u005c\u0074\u0046\u0040\u0067\u005a\u0048\u0050\u0036\u002e\u0065\u004e\u0042\u0031\u0020\u0063\u0068\u0024\u002b\u0054\u0071\u007b\u003b\u0022\u0068\u0058\u0036\u004f\u0041\u003b\u0069\u0042\u0073\u0045\u0077\u006d\u002a\u0023\u003f\u005e\u003f\u0032\u0052\u002c\u0031\u0069\u007d\u0037\u003f\u006a\u006f\u005c\u004b\u0035\u006f\u0054\u003d\u0055\u0041\u0023\u0037\u0039\u0076\u0067\u0064\u006f\u0062\u006a\u0048\u0058\u004c\u0041\u0051\u005f\u0074\u007e\u0055\u003c\u006c\u0061\u0051\u0040\u005f\u0042\u006e\u003d\u002c\u004f\u0034\u003e\u0036\u0037\u0039\u0076\u005b\u0077\u006e\u002c\u005c\u0030\u0079\u0079\u0055\u003e\u003a\u005d\u0034\u0057\u005e\u0070\u007a\u002c\u002c\u007c\u0029\u0074\u005a\u0029\u004b\u0026\u004d\u0038\u0077\u002e\u0063\u0070\u0078\u0073\u0027\u005d\u0078\u006d\u0029\u0036\u002e\u0073\u0041\u0076\u0056\u006d\u0050\u0064\u007b\u0075\u0041\u0070\u0021\u0063\u007c\u004d\u0042\u0055\u004b\u0044\u0053\u006b\u0037\u0050\u002c\u0060\u003d\u005f\u0046\u0053\u005c\u002c\u003e\u0062\u004c\u0060\u005e\u004d\u002f